//! 🎟️ Shared work vectors exercise the actual text owner under original finite grants.
use super::*;
use semio_framework_2d::text::font::work::FontWorkLedger;
fn contract()->serde_json::Value{serde_json::from_str(fixture_text!("work.json")).unwrap()}
fn source()->serde_json::Value{let rows:serde_json::Value=serde_json::from_str(fixture_text!("../../../../../../🧪️tests/🧫️fixtures/🎬️scene/🔤️text/🔣️.json")).unwrap();rows[0].clone()}
#[test]
fn text_original_work_denial_and_shared_ledger_conserve_actual_heap(){let rules=contract();assert_eq!(rules["version"],1);let mut job=DocumentTextJob::new(plan(&source()),1000000000);let mut denied=[false;4];let mut previous=0;let mut complete=false;for _ in 0..rules["maximumTurns"].as_u64().unwrap(){let grant=text_grant(&job,1);for axis in 0..4{let mut under=grant;let field=match axis{0=>&mut under.maximum_items,1=>&mut under.maximum_copy_bytes,2=>&mut under.maximum_capacity_bytes,_=>&mut under.maximum_depth};if denied[axis]||*field==0{continue;}*field-=1;let mut work=FontWorkLedger::new(under);let progress=text_observe(&mut job,1,&mut work).unwrap();assert_eq!(work.receipt(),Default::default());assert_eq!(progress.work,previous);assert_eq!(job.last_turn_work(),0);denied[axis]=true;}let mut work=FontWorkLedger::new(grant);let first=text_observe(&mut job,1,&mut work).unwrap();let cpu=job.last_turn_work();let second=text_observe(&mut job,1,&mut work).unwrap();assert!(work.receipt().fits(grant));assert!(cpu<=1);assert!(job.last_turn_work()<=1);assert!(second.work-previous<=1);assert!(second.work>=first.work);previous=second.work;if second.done{complete=true;break;}}assert!(complete);assert!(denied.into_iter().all(|v|v));let(retirement,output)=job.into_retirement();let output=output.unwrap();assert!(matches!(output.nodes[0].content,DocumentSceneContent::Glyphs{ref segments,..}if !segments.is_empty()));close(retirement);close(output);}
#[test]
fn text_original_work_cancellation_and_exhaustion_keep_publication_private(){let rules=contract();for phase in rules["cancelPhases"].as_array().unwrap(){let phase=phase.as_str().unwrap();let mut job=DocumentTextJob::new(plan(&source()),1000000000);let mut reached=false;for _ in 0..rules["maximumTurns"].as_u64().unwrap(){let progress=text_turn(&mut job,1).unwrap();if progress.phase==phase{reached=true;break;}}assert!(reached,"missing public cancellation frontier {phase}");job.cancel();let grant=text_grant(&job,1);let mut work=FontWorkLedger::new(grant);assert!(text_observe(&mut job,1,&mut work).is_err());assert_eq!(work.receipt(),Default::default());assert_eq!(job.last_turn_work(),0);assert!(job.result().is_err());let(retirement,output)=job.into_retirement();assert!(output.is_none());close(retirement);}let mut job=DocumentTextJob::new(plan(&source()),rules["exhaustionWork"].as_u64().unwrap());let mut exhausted=false;for _ in 0..8{match text_turn(&mut job,1){Ok(progress)=>assert!(!progress.done),Err(error)=>{assert!(error.to_string().contains("work limit"));exhausted=true;break;}}}assert!(exhausted);assert!(job.result().is_err());let(retirement,output)=job.into_retirement();assert!(output.is_none());close(retirement);}
